import{_ as d,o as a,c as i,a2 as e}from"./chunks/framework.DXRWYp4X.js";const k=JSON.parse('{"title":"20 · 训练计划：24 个月与验收物","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://R2h1.github.io/fullstack-learning-site/20-训练计划与里程碑"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"20 · 训练计划：24 个月与验收物 | 全栈 × AI 学习路径"}],["meta",{"property":"og:description","content":"面试级 · 生产级 · 企业级的全栈 + AI 学习课程（个人笔记，内容优先）"}],["meta",{"property":"og:url","content":"https://R2h1.github.io/fullstack-learning-site/20-训练计划与里程碑"}],["meta",{"name":"twitter:card","content":"summary"}]]},"headers":[],"relativePath":"20-训练计划与里程碑.md","filePath":"20-训练计划与里程碑.md","lastUpdated":1793501444000}'),r={name:"20-训练计划与里程碑.md"};function s(l,t,n,h,o,p){return a(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="_20-·-训练计划-24-个月与验收物" tabindex="-1">20 · 训练计划：24 个月与验收物 <a class="header-anchor" href="#_20-·-训练计划-24-个月与验收物" aria-label="Permalink to &quot;20 · 训练计划：24 个月与验收物&quot;">​</a></h1><blockquote><p>达标目标：<strong>按本计划执行到第 24 个月，凑齐「地表最强」的验收物清单；每月末用本章的复盘模板交作业给自己。</strong> 一句话理由：教材读得再熟，验收物为零就是零。计划的作用不是排课表，是把「学完」换成「交付了什么」。 衔接：19 章（D1–D5 分级）；21–24 章（长矛与证据）。</p></blockquote><hr><h2 id="_1-总目标与验收物计数" tabindex="-1">1. 总目标与验收物计数 <a class="header-anchor" href="#_1-总目标与验收物计数" aria-label="Permalink to &quot;1. 总目标与验收物计数&quot;">​</a></h2><p>终点不是「学完」，是下面这张表填满：</p><table tabindex="0"><thead><tr><th>#</th><th>验收物</th><th>D 层</th><th>判据</th></tr></thead><tbody><tr><td>1</td><td>算法：力扣 200+，medium 20 分钟 AC 率 &gt;70%</td><td>门票</td><td>周统计截图，AC 时间分布</td></tr><tr><td>2</td><td>项目一：高并发 SaaS 后端，真实 50–500 用户</td><td>D3</td><td>QPS / P99 / 单位成本 三组数字 + 一次故障复盘</td></tr><tr><td>3</td><td>项目二：生产级 RAG，带评估报告</td><td>D4</td><td>Recall@k、Faithfulness 曲线、优化前后对比、token 账单</td></tr><tr><td>4</td><td>引擎仓库一：mini-vLLM 调度器（continuous batching）</td><td>D4</td><td>带吞吐压测报告，TTFT/TPOT 对比</td></tr><tr><td>5</td><td>引擎仓库二：Raft 集群实现</td><td>D4</td><td>通过正确性测试（网络分区/节点宕机场景）</td></tr><tr><td>6</td><td>引擎仓库三：LSM 存储引擎 + 简易 MQ</td><td>D4</td><td>各自的正确性测试与基准</td></tr><tr><td>7</td><td>微调实证：LoRA 微调一个小模型解决一个真实分类任务</td><td>D4</td><td>训练配置、eval 指标、成本</td></tr><tr><td>8</td><td>开源：主流 AI/后端项目被 merge 的 PR ≥1</td><td>D5</td><td>PR 链接 + review 过程</td></tr><tr><td>9</td><td>输出：深度技术文 ≥10 篇，其中 1 篇被同行转发</td><td>D5</td><td>链接与阅读/转发数据</td></tr><tr><td>10</td><td>简历：用项目锚点 + 数字重写</td><td>—</td><td>每条 bullet 能被追问三层</td></tr></tbody></table><p><strong>计数规则</strong>：一项没有对应仓库/报告/链接，就不算完成。「看完了」不进入这张表。</p><h2 id="_2-每日与每周轨道" tabindex="-1">2. 每日与每周轨道 <a class="header-anchor" href="#_2-每日与每周轨道" aria-label="Permalink to &quot;2. 每日与每周轨道&quot;">​</a></h2><p>时间预算沿用路线图的 12–15 h/周，切成三条并行轨道，任何阶段都不停：</p><table tabindex="0"><thead><tr><th>轨道</th><th>频率</th><th>单次时长</th><th>内容</th></tr></thead><tbody><tr><td>🗡️ 长矛</td><td>每周 4 次</td><td>90–120 min</td><td>引擎实现，必须产出 commit</td></tr><tr><td>📖 教材</td><td>每周 3 次</td><td>60–90 min</td><td>01–18 章，读完当场写 1 条「我怎么验证它」</td></tr><tr><td>🧮 算法</td><td>每天</td><td>30–45 min</td><td>1 新题 + 1 复习，周日晚统计 AC 率</td></tr></tbody></table><p>长矛与教材的比例在阶段二调整为 6:2，阶段三（面试冲刺）调整为 3:3:2 加模拟面试。</p><h2 id="_3-三阶段排期" tabindex="-1">3. 三阶段排期 <a class="header-anchor" href="#_3-三阶段排期" aria-label="Permalink to &quot;3. 三阶段排期&quot;">​</a></h2><h3 id="阶段一-第-1–9-个月-宽环到-d3-门票打磨" tabindex="-1">阶段一（第 1–9 个月）：宽环到 D3 + 门票打磨 <a class="header-anchor" href="#阶段一-第-1–9-个月-宽环到-d3-门票打磨" aria-label="Permalink to &quot;阶段一（第 1–9 个月）：宽环到 D3 + 门票打磨&quot;">​</a></h3><ul><li>教材：01–18 全过一遍到 L2，其中 08/09/11/12/13/15/16 到 L3</li><li>项目一（SaaS 后端）全程并行：第 2 月上线、第 4 月引入真实用户、第 6 月制造并复盘一次容量故障</li><li>算法：100 题起步，建立题型地图（22 章的算法部分或外部题单）</li><li><strong>里程碑验收</strong>：项目一有公网地址 + 三组数字；算法 100 题；教材 L2 全绿</li></ul><h3 id="阶段二-第-10–18-个月-两把长矛到-d4" tabindex="-1">阶段二（第 10–18 个月）：两把长矛到 D4 <a class="header-anchor" href="#阶段二-第-10–18-个月-两把长矛到-d4" aria-label="Permalink to &quot;阶段二（第 10–18 个月）：两把长矛到 D4&quot;">​</a></h3><ul><li>长矛一（21 章 AI 推理层）：nanoGPT 路线 → LoRA 微调 → vLLM 使用与压测 → mini-vLLM</li><li>长矛二（22 章 分布式内核）：Raft → LSM → 简易 MQ</li><li>项目二（生产级 RAG，23 章评估体系）作为两把长矛的交汇点：既是分布式系统，又需要推理与评估判断</li><li><strong>里程碑验收</strong>：验收物 3/4/5/6/7 全部有仓库和报告</li></ul><h3 id="阶段三-第-19–24-个月-证据收口-市场验证" tabindex="-1">阶段三（第 19–24 个月）：证据收口 + 市场验证 <a class="header-anchor" href="#阶段三-第-19–24-个月-证据收口-市场验证" aria-label="Permalink to &quot;阶段三（第 19–24 个月）：证据收口 + 市场验证&quot;">​</a></h3><ul><li>24 章：开源 PR、深度写作、简历重写、模拟面试（系统设计 + 项目深挖各 5 轮）</li><li>项目一/二持续运营，把数字做厚（留存、营收或成本下降的任意一个真实指标）</li><li>真实投递：以「拿头部 offer」为验证，不以「过面」为目标</li><li><strong>里程碑验收</strong>：验收物 8/9/10</li></ul><h2 id="_4-选型口径-消除站点与路线图的矛盾" tabindex="-1">4. 选型口径（消除站点与路线图的矛盾） <a class="header-anchor" href="#_4-选型口径-消除站点与路线图的矛盾" aria-label="Permalink to &quot;4. 选型口径（消除站点与路线图的矛盾）&quot;">​</a></h2><p><strong>教材主线用 Fastify + Prisma + MySQL</strong>（通用企业级定位，01–18 章不动）。</p><p><strong>两个旗舰项目与长矛统一用</strong>：</p><table tabindex="0"><thead><tr><th>层</th><th>选型</th><th>理由</th></tr></thead><tbody><tr><td>后端框架</td><td>NestJS（TS）</td><td>DI/模块化对标 Spring，讲「架构取舍」最有料；14 章的迁移逻辑成立</td></tr><tr><td>数据库</td><td>PostgreSQL + pgvector</td><td>AI 项目向量与业务数据同库，省一层基础设施</td></tr><tr><td>ORM</td><td>Prisma</td><td>教材已覆盖，迁移零成本</td></tr><tr><td>AI 服务</td><td>Python + FastAPI</td><td>模型生态只在 Python 侧；mini-vLLM 也用它写</td></tr><tr><td>推理</td><td>vLLM（使用与压测）→ 自建 mini-vLLM（学习）</td><td>会用与懂原理分层取证</td></tr><tr><td>评估</td><td>RAGAS + Langfuse</td><td>一个给指标，一个给 trace</td></tr></tbody></table><p>对照表（14/07 章的概念可直接映射）：Fastify 钩子 ↔ NestJS 拦截器/管道；Express ↔ Spring MVC；Prisma 迁移 ↔ Flyway。</p><h2 id="_5-每月复盘模板" tabindex="-1">5. 每月复盘模板 <a class="header-anchor" href="#_5-每月复盘模板" aria-label="Permalink to &quot;5. 每月复盘模板&quot;">​</a></h2><p>每月最后一天，30 分钟填完，存进项目仓库的 <code>journal/</code> 目录（同时也是 D5 输出的素材）：</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## YYYY-MM 复盘</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 长矛进度：本周 commit N 次，卡在 ___（具体到函数/测试名）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 验收物增量：新增 </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">___（链接），仍缺 ___</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 教材回填：本月把 </span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">___ 章的一处说法改掉了，因为实践中 ___</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 数字：算法 AC 率 __%；项目真实用户 __；token 成本 __</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 下月唯一重点：___</span></span></code></pre></div><p>「教材回填」是硬要求：实践中发现站点讲得不准，就回去改章节。这也是站点从「教材」变成「活文档」的方式。</p><h2 id="_6-风险与止损" tabindex="-1">6. 风险与止损 <a class="header-anchor" href="#_6-风险与止损" aria-label="Permalink to &quot;6. 风险与止损&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>症状</th><th>处置</th></tr></thead><tbody><tr><td>只刷教材不做</td><td>连续两周无 commit</td><td>长矛优先砍到每天 30 min，也要保住动手</td></tr><tr><td>引擎烂尾</td><td>有 repo 无测试</td><td>停止开新坑，先用测试收口上一个</td></tr><tr><td>项目无用户</td><td>数字全是压测</td><td>阶段一结束前必须公开上线，哪怕只有 20 个真实用户</td></tr><tr><td>时间崩盘</td><td>三轨道全断</td><td>保留算法 + 长矛，教材暂停（教材可以面试前突击）</td></tr></tbody></table><h2 id="_7-达标标准" tabindex="-1">7. 达标标准 <a class="header-anchor" href="#_7-达标标准" aria-label="Permalink to &quot;7. 达标标准&quot;">​</a></h2><p><strong>执行：</strong></p><ul><li>[ ] 三轨道连续 4 周无中断，有 commit 与 journal 记录</li><li>[ ] 阶段一末：验收物 1、2 达成</li><li>[ ] 阶段二末：验收物 3–7 达成</li><li>[ ] 阶段三末：验收物 8–10 达成</li></ul>`,32)])])}const g=d(r,[["render",s]]);export{k as __pageData,g as default};
